const fs = require('fs')
const path = require('path')
const os = require('os')
const { verifyLicenseSignature } = require('./license_signing')

// ── Ed25519 verification ─────────────────────────────────────────────────────
// Licenses issued by server/ carry a `sig` over the canonical fields; the app
// verifies it with this bundled PUBLIC key (generated by server/keygen.js).
// The private key never ships, so a saved license cannot be forged from
// anything inside the app. Older unsigned licenses, checksummed with a secret
// that shipped with the app, are no longer trusted: an online check replaces
// them, and only a signed record grants offline access.
const PUBLIC_KEY_FILE = path.join(__dirname, 'license_public_key.pem')
let PUBLIC_KEY = null
try {
  PUBLIC_KEY = fs.readFileSync(PUBLIC_KEY_FILE, 'utf8')
} catch (_) {
  /* not generated yet */
}
// Overridable for tests.
const LICENSE_FILE = process.env.CH_LICENSE_FILE || path.join(os.homedir(), '.ch_toolkit_license')

/**
 * The license an account record (Firestore REST fields) grants this machine, as saveLicense
 * takes it. A signed record carries the exact strings the owner's admin panel signed: save
 * those, so the offline check verifies the bytes that were signed. A record signed before the
 * panel stored one of them falls back to the record's own value.
 */
function licenseFromRecord(fields, email, machineId) {
  return {
    email,
    // Every sign-in rewrites `name` with the Google profile name, so a renamed account would no
    // longer match its signature. licName keeps the name as signed, even an empty one.
    name: fields.licName?.stringValue ?? (fields.name?.stringValue || ''),
    machineId,
    expiresOn: fields.licExpiresOn?.stringValue || fields.expiresOn?.timestampValue,
    activatedOn: fields.licActivatedOn?.stringValue || fields.activatedOn?.timestampValue || new Date().toISOString(),
    sig: fields.sig?.stringValue,
  }
}

/** Save offline access for a signed license; without a signature, any saved license goes. */
function saveLicense(licenseData) {
  if (!licenseData.sig) {
    clearLicense()
    return false
  }
  const data = {
    email: licenseData.email,
    name: licenseData.name,
    machineId: licenseData.machineId,
    expiresOn: licenseData.expiresOn,
    activatedOn: licenseData.activatedOn,
    savedAt: new Date().toISOString(),
    sig: licenseData.sig,
  }
  fs.writeFileSync(LICENSE_FILE, JSON.stringify(data), 'utf8')
  return true
}

function loadLicense() {
  try {
    if (!fs.existsSync(LICENSE_FILE)) return null
    const data = JSON.parse(fs.readFileSync(LICENSE_FILE, 'utf8'))
    delete data.checksum
    if (!data.sig) return null
    if (!PUBLIC_KEY) {
      console.log('License is signed but no public key is bundled!')
      return null
    }
    const { sig, ...fields } = data
    if (!verifyLicenseSignature(fields, sig, PUBLIC_KEY)) {
      console.log('License signature invalid!')
      return null
    }
    return data
  } catch {
    return null
  }
}

function getDaysRemaining(expiresOn) {
  let expiry
  try {
    expiry = new Date(expiresOn).getTime()
  } catch (_) {
    return 0
  }
  const ms = expiry - Date.now()
  if (!Number.isFinite(ms) || ms <= 0) return 0 // malformed or expired: no phantom day
  return Math.floor(ms / (1000 * 60 * 60 * 24))
}

function clearLicense() {
  try {
    fs.unlinkSync(LICENSE_FILE)
  } catch {}
}

// Single source of truth for offline license validation. Used by both the
// boot auto-login path and the check-license offline fallback so the rules
// (account match, machine lock, expiry) can never drift apart (R2).
//   - currentMachineId: the machine id of this device
//   - email: optional; when provided, the saved license must belong to it
// Returns the same { allowed, reason, ... } shape as check-license.
function validateOfflineLicense(currentMachineId, email) {
  const localLicense = loadLicense()
  if (!localLicense) {
    return { allowed: false, reason: 'no_internet' }
  }
  if (email && localLicense.email !== email) {
    return { allowed: false, reason: 'wrong_account' }
  }
  if (localLicense.machineId !== currentMachineId) {
    return { allowed: false, reason: 'wrong_machine' }
  }
  const daysLeft = getDaysRemaining(localLicense.expiresOn)
  if (!Number.isFinite(daysLeft) || daysLeft <= 0) {
    clearLicense()
    return { allowed: false, reason: 'expired' }
  }
  return { allowed: true, daysLeft, offline: true, email: localLicense.email }
}

// Tests verify licenses they sign with their own key pair.
function _usePublicKey(key) {
  PUBLIC_KEY = key
}

module.exports = {
  licenseFromRecord,
  saveLicense,
  loadLicense,
  getDaysRemaining,
  clearLicense,
  validateOfflineLicense,
  _usePublicKey,
}
